let particles = [];
let r = 75;

function setup() {
  createCanvas(windowWidth, windowHeight);
  colorMode(HSB, 100);
  noStroke();

  background(0);
  updateParticles();
}

function draw() {
  for (let p of particles) {
    p.draw();
    p.move();
  }
}

function updateParticles() {
  particles = [];
	let n = 600;
  for (let i = 0; i < n; i++) {
		let theta = map(i, 0, n, -PI, PI);
    let x_ = width/2 + r*cos(theta);
    let y_ = height/2 + r*sin(theta);
		let s_ = 2;
    let c_ = color(i/6, 100, i%100);
    particles.push(new Particle(x_, y_, s_, c_, theta, true));
  }
