function Particle(x_, y_, s_, c_, theta_, out_) {
  this.x = x_;
  this.y = y_;
  this.size = s_;
  this.c = c_;
  this.theta = theta_
  this.out = out_;

  this.alpha = 100;
  this.dist = 1;

  this.move = function() {
    let d = dist(this.x, this.y, width/2, height/2);
		let angle = atan2(this.y - height/2, this.x - width/2)
    if (this.out) {
      angle += map(d, r*2, 0, PI*2, PI);
    } else {
      angle += map(d, r*2, 0, PI, PI*2);
    }
    let v = p5.Vector.fromAngle(angle, this.dist);
    this.x += v.x;
    this.y += v.y;
    //this.dist *= 0.999;
    //this.alpha *= 0.999;
		//this.size *= 0.999;
    if (d > r * 3 - 1) {
      this.out = false;
    } else if (d < r + 1) {
      this.out = true;
    }
  }

  this.draw = function() {
    this.c.setAlpha(this.alpha);
    fill(this.c);
    circle(this.x, this.y, this.size);
    this.c.setAlpha(100);
  }
}
